import{_ as p,a0 as d,w as o,s as r,I as a,x as n,a1 as i,A as l,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用 ncdu 检查 Linux 中的可用磁盘空间 | LCTT x X-CMD","titleTemplate":false,"description":"用 ncdu 检查 Linux 中的可用磁盘空间 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 ncdu 检查 Linux 中的可用磁盘空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 ncdu 检查 Linux 中的可用磁盘空间 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210819 Check free disk space in Linux with ncdu","title":"用 ncdu 检查 Linux 中的可用磁盘空间","tag":"202108","desc":""},"relativePath":"202108/20210819 Check free disk space in Linux with ncdu.md","filePath":"[post].md"}'),u={name:"202108/20210819 Check free disk space in Linux with ncdu.md"};function c(h,s,k,g,f,b){const e=d("Link");return o(),r("div",null,[s[33]||(s[33]=a("h1",{id:"用-ncdu-检查-linux-中的可用磁盘空间",tabindex:"-1"},[n("用 ncdu 检查 Linux 中的可用磁盘空间 "),a("a",{class:"header-anchor",href:"#用-ncdu-检查-linux-中的可用磁盘空间","aria-label":"Permalink to “用 ncdu 检查 Linux 中的可用磁盘空间”"},"​")],-1)),s[34]||(s[34]=a("blockquote",null,[a("p",null,"用 ncdu Linux 命令获得关于磁盘使用的交互式报告。")],-1)),s[35]||(s[35]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/29/095819e87oz4ox6p40t6q0.jpg",alt:""})],-1)),a("p",null,[s[2]||(s[2]=n("计算机用户多年来往往积累了大量的数据，无论是重要的个人项目、数码照片、视频、音乐还是代码库。虽然现在的硬盘往往相当大，但有时你必须退一步，评估一下你在硬盘上实际存储了什么。经典的 Linux 命令 ",-1)),i(e,{href:"https://opensource.com/article/21/7/check-disk-space-linux-df"},{default:l(()=>[...s[0]||(s[0]=[n("df",-1)])]),_:1}),s[3]||(s[3]=n(" 和 ",-1)),i(e,{href:"https://opensource.com/article/21/7/check-disk-space-linux-du"},{default:l(()=>[...s[1]||(s[1]=[n("du",-1)])]),_:1}),s[4]||(s[4]=n(" 是快速了解硬盘上的内容的方法，它们提供了一个可靠的报告，易于解析和处理。这对脚本和处理来说是很好的，但人的大脑对数百行的原始数据并不总是反应良好。认识到这一点，",-1)),s[5]||(s[5]=a("code",null,"ncdu",-1)),s[6]||(s[6]=n(" 命令旨在提供一份关于你在硬盘上使用的空间的交互式报告。",-1))]),s[36]||(s[36]=t('<h3 id="在-linux-上安装-ncdu" tabindex="-1">在 Linux 上安装 ncdu <a class="header-anchor" href="#在-linux-上安装-ncdu" aria-label="Permalink to “在 Linux 上安装 ncdu”">​</a></h3><p>在 Linux 上，你可以从你的软件仓库安装 <code>ncdu</code>。例如，在 Fedora 或 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncdu</span></span></code></pre></div>',3)),a("p",null,[s[8]||(s[8]=n("在 BSD 上，你可以使用 ",-1)),i(e,{href:"https://opensource.com/article/19/11/pkgsrc-netbsd-linux"},{default:l(()=>[...s[7]||(s[7]=[n("pkgsrc",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),a("p",null,[s[12]||(s[12]=n("在 macOS 上，你可以从 ",-1)),i(e,{href:"https://opensource.com/article/20/11/macports"},{default:l(()=>[...s[10]||(s[10]=[n("MacPorts",-1)])]),_:1}),s[13]||(s[13]=n(" 或 ",-1)),i(e,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:l(()=>[...s[11]||(s[11]=[n("HomeBrew",-1)])]),_:1}),s[14]||(s[14]=n(" 安装。",-1))]),a("p",null,[s[16]||(s[16]=n("另外，你也可以 ",-1)),i(e,{href:"https://dev.yorhel.nl/ncdu"},{default:l(()=>[...s[15]||(s[15]=[n("从源码编译 ncdu",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[37]||(s[37]=t(`<h3 id="使用-ncdu" tabindex="-1">使用 ncdu <a class="header-anchor" href="#使用-ncdu" aria-label="Permalink to “使用 ncdu”">​</a></h3><p><code>ncdu</code> 界面使用 ncurses 库，它将你的终端窗口变成一个基本的图形应用，所以你可以使用方向键来浏览菜单。</p><p><img src="https://opensource.com/sites/default/files/ncdu.jpg" alt="ncdu interface" title="ncdu interface"></p><p>这是 <code>ncdu</code> 的主要吸引力之一，也是它与最初的 <code>du</code> 命令不同的地方。</p><p>要获得一个目录的完整列表，启动 <code>ncdu</code>。它默认为当前目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu</span></span>
<span class="line"><span>ncdu 1.16 ~ Use the arrow keys to navigate, press ? for help                                                                  </span></span>
<span class="line"><span>--- /home/tux -----------------------------------------------</span></span>
<span class="line"><span>   22.1 GiB [##################] /.var</span></span>
<span class="line"><span>   19.0 GiB [###############   ] /Iso</span></span>
<span class="line"><span>   10.0 GiB [########          ] /.local</span></span>
<span class="line"><span>    7.9 GiB [######            ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>    3.6 GiB [##                ] /.mail</span></span>
<span class="line"><span>    2.9 GiB [##                ] /Code</span></span>
<span class="line"><span>    2.8 GiB [##                ] /Documents</span></span>
<span class="line"><span>    2.3 GiB [#                 ] /Videos</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>这个列表首先显示了最大的目录（在这个例子中，那是 <code>~/.var</code> 目录，塞满了很多的 flatpak 包）。</p><p>使用键盘上的方向键，你可以浏览列表，深入到一个目录，这样你就可以更好地了解什么东西占用了最大的空间。</p><h3 id="获取一个特定目录的大小" tabindex="-1">获取一个特定目录的大小 <a class="header-anchor" href="#获取一个特定目录的大小" aria-label="Permalink to “获取一个特定目录的大小”">​</a></h3><p>你可以在启动 <code>ncdu</code> 时提供任意一个文件夹的路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu ~/chromiumos</span></span></code></pre></div><h3 id="排除目录" tabindex="-1">排除目录 <a class="header-anchor" href="#排除目录" aria-label="Permalink to “排除目录”">​</a></h3><p>默认情况下，<code>ncdu</code> 包括一切可以包括的东西，包括符号链接和伪文件系统，如 procfs 和 sysfs。你可以用 <code>--exclude-kernfs</code> 来排除这些。</p><p>你可以使用 <code>--exclude</code> 选项排除任意文件和目录，并在后面加上一个匹配模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --exclude &quot;.var&quot;</span></span>
<span class="line"><span>   19.0 GiB [##################] /Iso</span></span>
<span class="line"><span>   10.0 GiB [#########         ] /.local</span></span>
<span class="line"><span>    7.9 GiB [#######           ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>另外，你可以在文件中列出要排除的文件和目录，并使用 <code>--exclude-from</code> 选项来引用该文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --exclude-from myexcludes.txt /home/tux</span></span>
<span class="line"><span>   10.0 GiB [#########         ] /.local</span></span>
<span class="line"><span>    7.9 GiB [#######           ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="颜色方案" tabindex="-1">颜色方案 <a class="header-anchor" href="#颜色方案" aria-label="Permalink to “颜色方案”">​</a></h3><p>你可以用 <code>--color dark</code> 选项给 <code>ncdu</code> 添加一些颜色。</p><p><img src="https://opensource.com/sites/default/files/ncdu-dark.jpg" alt="ncdu color scheme" title="ncdu color scheme"></p><h3 id="包括符号链接" tabindex="-1">包括符号链接 <a class="header-anchor" href="#包括符号链接" aria-label="Permalink to “包括符号链接”">​</a></h3><p><code>ncdu</code> 输出按字面意思处理符号链接，这意味着一个指向 9GB 文件的符号链接只占用 40 个字节。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu ~/Iso</span></span>
<span class="line"><span>    9.3 GiB [##################]  CentOS-Stream-8-x86_64-20210427-dvd1.iso                                                    </span></span>
<span class="line"><span>@   0.0   B [                  ]  fake.iso</span></span></code></pre></div><p>你可以用 <code>--follow-symlinks</code> 选项强制 ncdu 跟踪符号链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --follow-symlinks ~/Iso</span></span>
<span class="line"><span>    9.3 GiB [##################]  fake.iso                                                                                    </span></span>
<span class="line"><span>    9.3 GiB [##################]  CentOS-Stream-8-x86_64-20210427-dvd1.iso</span></span></code></pre></div><h3 id="磁盘使用率" tabindex="-1">磁盘使用率 <a class="header-anchor" href="#磁盘使用率" aria-label="Permalink to “磁盘使用率”">​</a></h3><p>磁盘空间用完并不有趣，所以监控你的磁盘使用情况很重要。<code>ncdu</code> 命令使它变得简单和互动。下次当你对你的电脑上存储的东西感到好奇时，或者只是想以一种新的方式探索你的文件系统时，不妨试试 <code>ncdu</code>。</p><hr>`,28)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/21/8/ncdu-check-free-disk-space-linux"},{default:l(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/21/8/ncdu-check-free-disk-space-linux",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[20]||(s[20]=[n("Seth Kenlon",-1)])]),_:1}),s[25]||(s[25]=n(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[30]||(s[30]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[29]||(s[29]=[n("Linux中国",-1)])]),_:1}),s[32]||(s[32]=n(" 荣誉推出",-1))])])}const y=p(u,[["render",c]]);export{C as __pageData,y as default};
